def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda x: sum(r.count(x) for r in g))
    divider = next((r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] != bg), None)
    if divider is None:
        return g
    divcolor = g[divider][0]
    objcolor = next((v for row in g for v in row if v not in (bg, divcolor)), None)
    if objcolor is None:
        return g
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == objcolor]
    rmin, rmax = min(r for r, c in cells), max(r for r, c in cells)
    cmin, cmax = min(c for r, c in cells), max(c for r, c in cells)
    shape = [(r-rmin, c-cmin) for r, c in cells]
    oh, ow = rmax-rmin+1, cmax-cmin+1
    if rmin > divider:
        nr = divider + 1
        marker = nr + oh
    else:
        nr = divider - oh
        marker = nr - 1
    nc = cmin
    for r in range(h):
        for c in range(w):
            if g[r][c] == objcolor:
                g[r][c] = bg
    if 0 <= nr and nr+oh <= h:
        for dr, dc in shape:
            g[nr+dr][nc+dc] = objcolor
        if 0 <= marker < h and marker != divider:
            g[marker] = [8] * w
    return g
